  1487    /**************************************************************************
  1488     *
  1489     * @Function:
  1490     *   tt_apply_mvar
  1491     *
  1492     * @Description:
  1493     *   Apply `MVAR' table adjustments.
  1494     *
  1495     * @InOut:
  1496     *   face ::
  1497     *     The font face.
  1498     */
  1499    FT_LOCAL_DEF( void )
  1500    tt_apply_mvar( FT_Face  face )  /* TT_Face */
  1501    {
  1502      TT_Face  ttface = (TT_Face)face;
  1503
  1504      GX_Blend  blend = ttface->blend;
  1505      GX_Value  value, limit;
  1506
  1507      FT_Short  mvar_hasc_delta = 0;
  1508      FT_Short  mvar_hdsc_delta = 0;
  1509      FT_Short  mvar_hlgp_delta = 0;
  1510
  1511
  1512      if ( !( ttface->variation_support & TT_FACE_FLAG_VAR_MVAR ) )
  1513        return;
  1514
  1515      value = blend->mvar_table->values;
  1516      limit = FT_OFFSET( value, blend->mvar_table->valueCount );
  1517
  1518      for ( ; value < limit; value++ )
  1519      {
  1520        FT_Short*  p = ft_var_get_value_pointer( ttface, value->tag );
  1521        FT_Int     delta;
  1522
  1523
  1524        delta = tt_var_get_item_delta( face,
  1525                                       &blend->mvar_table->itemStore,
  1526                                       value->outerIndex,
  1527                                       value->innerIndex );
  1528
  1529        if ( p && delta )
  1530        {
  1531          FT_TRACE5(( "value %c%c%c%c (%d unit%s) adjusted by %d unit%s (MVAR)\n",
  1532                      (FT_Char)( value->tag >> 24 ),
  1533                      (FT_Char)( value->tag >> 16 ),
  1534                      (FT_Char)( value->tag >> 8 ),
  1535                      (FT_Char)( value->tag ),
  1536                      value->unmodified,
  1537                      value->unmodified == 1 ? "" : "s",
  1538                      delta,
  1539                      delta == 1 ? "" : "s" ));
  1540
  1541          /* since we handle both signed and unsigned values as FT_Short, */
  1542          /* ensure proper overflow arithmetic                            */
  1543          *p = (FT_Short)( value->unmodified + (FT_Short)delta );
  1544
  1545          /* Treat hasc, hdsc and hlgp specially, see below. */
  1546          if ( value->tag == MVAR_TAG_HASC )
  1547            mvar_hasc_delta = (FT_Short)delta;
  1548          else if ( value->tag == MVAR_TAG_HDSC )
  1549            mvar_hdsc_delta = (FT_Short)delta;
  1550          else if ( value->tag == MVAR_TAG_HLGP )
  1551            mvar_hlgp_delta = (FT_Short)delta;
  1552        }
  1553      }
  1554
  1555      /* adjust all derived values */
  1556      {
  1557        FT_Service_MetricsVariations  var =
  1558          (FT_Service_MetricsVariations)ttface->face_var;
  1559
  1560        /*
  1561         * Apply the deltas of hasc, hdsc and hlgp to the FT_Face's ascender,
  1562         * descender and height attributes, no matter how they were originally
  1563         * computed.
  1564         *
  1565         * (Code that ignores those and accesses the font's metrics values
  1566         * directly is already served by the delta application code above.)
  1567         *
  1568         * The MVAR table supports variations for both typo and win metrics.
  1569         * According to Behdad Esfahbod, the thinking of the working group was
  1570         * that no one uses win metrics anymore for setting line metrics (the
  1571         * specification even calls these metrics "horizontal clipping
  1572         * ascent/descent", probably for their role on the Windows platform in
  1573         * computing clipping boxes), and new fonts should use typo metrics, so
  1574         * typo deltas should be applied to whatever sfnt_load_face decided the
  1575         * line metrics should be.
  1576         *
  1577         * Before, the following led to different line metrics between default
  1578         * outline and instances, visible when e.g. the default outlines were
  1579         * used as the regular face and instances for everything else:
  1580         *
  1581         * 1. sfnt_load_face applied the hhea metrics by default.
  1582         * 2. This code later applied the typo metrics by default, regardless of
  1583         *    whether they were actually changed or the font had the OS/2 table's
  1584         *    fsSelection's bit 7 (USE_TYPO_METRICS) set.
  1585         */
  1586        FT_Short  current_line_gap = face->height - face->ascender +
  1587                                     face->descender;
  1588
  1589
  1590        face->ascender  = face->ascender + mvar_hasc_delta;
  1591        face->descender = face->descender + mvar_hdsc_delta;
  1592        face->height    = face->ascender - face->descender +
  1593                          current_line_gap + mvar_hlgp_delta;
  1594
  1595        face->underline_position  = ttface->postscript.underlinePosition -
  1596                                    ttface->postscript.underlineThickness / 2;
  1597        face->underline_thickness = ttface->postscript.underlineThickness;
  1598
  1599        /* iterate over all FT_Size objects and call `var->size_reset' */
  1600        /* to propagate the metrics changes                            */
  1601        if ( var && var->size_reset )
  1602          FT_List_Iterate( &face->sizes_list,
  1603                           ft_size_reset_iterator,
  1604                           (void*)var );
  1605      }
  1606    }
