   135    static int
   136    archive_read_entry_data( struct archive   *ar,
   137                             vector<FT_Byte>  *vw )
   138    {
   139      int             r;
   140      const FT_Byte*  buff;
   141      size_t          size;
   142      int64_t         offset;
   143
   144      for (;;)
   145      {
   146        r = archive_read_data_block( ar,
   147                                     reinterpret_cast<const void**>( &buff ),
   148                                     &size,
   149                                     &offset );
   150        if ( r == ARCHIVE_EOF )
   151          return ARCHIVE_OK;
   152        if ( r != ARCHIVE_OK )
   153          return r;
   154
   155        vw->insert( vw->end(), buff, buff + size );
   156      }
   157    }
